#[path = "solution.rs"]
mod solution;

use solution::{FocusRing, Overlay, Page, UiState};

#[test]
fn empty_focus_ring_stays_at_zero() {
    let mut ring = FocusRing::new(0);
    assert_eq!(ring.index(), 0);
    ring.next();
    ring.previous();
    assert_eq!(ring.index(), 0);
}

#[test]
fn single_element_ring_never_leaves_zero() {
    let mut ring = FocusRing::new(1);
    ring.next();
    ring.previous();
    assert_eq!(ring.index(), 0);
}

#[test]
fn next_and_previous_visit_and_wrap_all_indices() {
    let mut ring = FocusRing::new(3);
    ring.next();
    assert_eq!(ring.index(), 1);
    ring.next();
    assert_eq!(ring.index(), 2);
    ring.next();
    assert_eq!(ring.index(), 0);
    ring.previous();
    assert_eq!(ring.index(), 2);
    ring.previous();
    assert_eq!(ring.index(), 1);
}

#[test]
fn changing_length_clamps_or_resets_as_required() {
    let mut ring = FocusRing::new(5);
    for _ in 0..4 {
        ring.next();
    }
    assert_eq!(ring.index(), 4);

    ring.set_len(3);
    assert_eq!(ring.index(), 2);
    ring.set_len(8);
    assert_eq!(ring.index(), 2);
    ring.set_len(0);
    assert_eq!(ring.index(), 0);
    ring.set_len(2);
    assert_eq!(ring.index(), 0);
}

#[test]
fn navigation_changes_only_the_page() {
    let mut state = UiState::new(3);
    state.overlay = Overlay::Filter;
    state.focus.next();
    let focus_before = state.focus.clone();

    state.navigate(Page::Queue);
    assert_eq!(state.page, Page::Queue);
    assert_eq!(state.overlay, Overlay::Filter);
    assert_eq!(state.focus, focus_before);
}

#[test]
fn closing_overlay_changes_only_the_overlay() {
    let mut state = UiState::new(4);
    state.page = Page::Lookup;
    state.overlay = Overlay::Help;
    state.focus.next();
    state.focus.next();
    let focus_before = state.focus.clone();

    state.close_overlay();
    assert_eq!(state.overlay, Overlay::None);
    assert_eq!(state.page, Page::Lookup);
    assert_eq!(state.focus, focus_before);
}

